block: fn f():
    fn outer(i, total):
        loop oi from i to 2:
            fn inner(j, acc):
                loop ij from j to 5:
                    if ij == 2:
                        return acc
                    return inner(ij + 1, acc + 1)
                acc
            return outer(oi + 1, total + inner(0, 0))
        total
    outer(0, 0)
